    (v_route, 'Katedrála Nanebevzetí Panny Marie v Rožňavě', 'Katedrála na Slovensku. Památka v Slovensku — kus historie přímo u trasy.', 48.66333, 20.53167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BE%C5%88ava%20-%20Barokovo-klasicistick%C3%A1%20zvonica%20-a.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BE%C5%88ava%20-%20Barokovo-klasicistick%C3%A1%20zvonica%20-a.jpg"}'::text[], 0, '{"en": {"name": "Assumption of Mary Church", "description": "Cathedral in Rožňava, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Kathedrale Mariä Himmelfahrt (Rožňava)", "description": "Kathedrale in der Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Wniebowzięcia Najświętszej Maryi Panny w Rožňavie", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Maria-Tenhemelopneming", "description": "Kathedraal in Rožňava, Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de la Asunción de la Virgen María", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de l''Assomption de Rožňava", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála Nanebevzetí Panny Marie v Rožňavě", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
