    (v_route, 'Katedrálný chrám svatého Jana Křtitele', 'Katedrála v Prešově. Památka v Slovensku — kus historie přímo u trasy.', 48.9941, 21.2429, 'http://commons.wikimedia.org/wiki/Special:FilePath/Slovakia%20Presov%20694.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Slovakia%20Presov%20694.JPG"}'::text[], 0, '{"en": {"name": "Cathedral of Saint John the Baptist", "description": "Greek Catholic cathedral in Prešov, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Katedrálný chrám svatého Jana Křtitele", "description": "Kathedrale in der Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra greckokatolicka św. Jana Chrzciciela w Preszowie", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Temple of St. John the Baptist", "description": "Kathedraal in Prešov, Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Juan Bautista", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Jean-Baptiste de Prešov", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrálný chrám svatého Jana Křtitele", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
