    (v_route, 'bazilika svaté Ludmily', 'Kostel na náměstí Míru v Praze na Vinohradech. Památka v Česku — kus historie přímo u trasy.', 50.07528, 14.43722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Prague-%20N%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Prague-%20N%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru.jpg"}'::text[], 6, '{"en": {"name": "Basilika of St. Ludmila", "description": "Church. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "St. Ludmilla", "description": "Kirchengebäude in Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Ludmiły w Pradze", "description": "Zabytkowa świątynia rzymskokatolicka w Czechach. Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Ludmillakerk", "description": "Kerkgebouw in Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Basílica de Santa Ludmila", "description": "Basílica ubicada en la ciudad de Praga, en la República Checa. Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "église Sainte-Ludmila", "description": "Église tchèque. Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "bazilika svaté Ludmily", "description": "Церква. Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb);
