    (v_route, 'Bazilika Povýšení svatého Kříže', 'Kostel. Památka v Slovensku — kus historie přímo u trasy.', 49.1375, 20.4297, 'http://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20of%20the%20Exaltation%20of%20the%20Holy%20Cross%2C%20Ke%C5%BEmarok1.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20of%20the%20Exaltation%20of%20the%20Holy%20Cross%2C%20Ke%C5%BEmarok1.JPG"}'::text[], 0, '{"en": {"name": "Bazilika povýšenia Sväteho Kríža", "description": "Church building in Kežmarok District, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Heilig-Kreuz-Basilika", "description": "Kirche in der Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół św. Krzyża w Kieżmarku", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Bazilika Povýšení svatého Kříže", "description": "Kerkgebouw in Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Bazilika Povýšení svatého Kříže", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Bazilika Povýšení svatého Kříže", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Bazilika Povýšení svatého Kříže", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
