    (v_route, 'Kanonie premonstrátů klášter Teplá', 'Premonstrátský klášter a opatství v západních Čechách. Památka v Česku — kus historie přímo u trasy.', 49.96639, 12.87833, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kl%20Tepl%C3%A1%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kl%20Tepl%C3%A1%201.jpg"}'::text[], 0, '{"en": {"name": "Teplá Abbey", "description": "National monument of the Czech Republic. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Stift Tepl", "description": "Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kanonie premonstrátů klášter Teplá", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Klooster van Teplá", "description": "Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Kanonie premonstrátů klášter Teplá", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Teplá", "description": "Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Kanonie premonstrátů klášter Teplá", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Zámek Kynžvart', 'Zámek v západních Čechách. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 50.00431, 12.60558, 'http://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Kyn%C5%BEvart%20celek%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Kyn%C5%BEvart%20celek%201.jpg"}'::text[], 1, '{"en": {"name": "Castle Kynžvart", "description": "Castle in Kynžvart, Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Schloss Königswart", "description": "Schloss in Tschechien, ehemals Sitz der Familie Metternich. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zámek Kynžvart", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "slot Kynžvart", "description": "Slot in de Tsjechische stad Lázně Kynžvart. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Zámek Kynžvart", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Kynžvart", "description": "Château et musée tchèque. Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Zámek Kynžvart", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
