    (v_route, 'Synagoga v Karlových Varech', 'Zaniklá   zděná   synagoga   (známka 600). Památka v Česku — kus historie přímo u trasy.', 50.2258, 12.8781, 'http://commons.wikimedia.org/wiki/Special:FilePath/Syna%20Karlsbad.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Syna%20Karlsbad.jpg"}'::text[], 4, '{"en": {"name": "Synagogue in Karlovy Vary", "description": "A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Ehemalige Synagoge in Karlsbad, Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Karlowych Warach", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Synagoga v Karlových Varech", "description": "Synagoge in Okres Karlsbad, Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Synagoga v Karlových Varech", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de Carlsbad", "description": "Ou synagogue de Karlovy Vary, en Tchéquie, inaugurée en 1877, détruite en 1938, lors de la nuit de Cristal. Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Synagoga v Karlových Varech", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
