    (v_route, 'Konkatedrála Nanebevzetí Panny Marie', 'Kostel v Opavě. Památka v Česku — kus historie přímo u trasy.', 49.93872, 17.90069, 'http://commons.wikimedia.org/wiki/Special:FilePath/Opava%2C%20konkatedr%C3%A1la%20Nanebevzet%C3%AD%20Panny%20Marie.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Opava%2C%20konkatedr%C3%A1la%20Nanebevzet%C3%AD%20Panny%20Marie.JPG"}'::text[], 0, '{"en": {"name": "Our Lady of the Assumption Co-Cathedral, Opava", "description": "Church in Opava District of Moravian Silesian region. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Mariä Himmelfahrt (Opava)", "description": "Kirchengebäude in Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Konkatedra Wniebowzięcia Najświętszej Maryi Panny w Opawie", "description": "Świątynia katolicka. Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Cattedrale di Opava", "description": "Kerkgebouw in Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Concatedral de Nuestra Señora de la Asunción", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Konkatedrála Nanebevzetí Panny Marie", "description": "Église tchèque. Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Konkatedrála Nanebevzetí Panny Marie", "description": "Церква в Чехії. Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
